cat > /tmp/parse_binlog.cs << 'EOF'
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        Console.WriteLine("=== BUILD RESULT ===");
        Console.WriteLine($"Succeeded: {build.Succeeded}");
        Console.WriteLine();

        // Collect all errors
        var errors = new List<(string project, string code, string message, string file, int line)>();
        build.VisitAllChildren<Error>(error => {
            var project = "";
            var parent = error.Parent;
            while (parent != null)
            {
                if (parent is Project p)
                {
                    project = p.Name;
                    break;
                }
                parent = (parent as TreeNode)?.Parent;
            }
            errors.Add((project, error.Code ?? "", error.Message ?? "", error.File ?? "", error.LineNumber));
        });

        Console.WriteLine($"=== ERRORS ({errors.Count} total) ===");
        foreach (var g in errors.GroupBy(e => e.project))
        {
            Console.WriteLine($"\n--- Project: {g.Key} ---");
            foreach (var e in g)
            {
                Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
            }
        }

        // Collect warnings that might be relevant
        Console.WriteLine("\n=== KEY WARNINGS ===");
        build.VisitAllChildren<Warning>(warning => {
            if (warning.Code != null && (warning.Code.StartsWith("NU") || warning.Code.StartsWith("MSB")))
            {
                Console.WriteLine($"  [{warning.Code}] {warning.Message}");
            }
        });
    }
}
EOF

